SET LOCAL lock_timeout = '1s';--> statement-breakpoint
SET LOCAL statement_timeout = '5s';--> statement-breakpoint

ALTER TABLE "flow_runs" ADD CONSTRAINT "flow_runs_state_fields_check" CHECK (("status" = 'pending' AND "error" IS NULL AND "finished_at" IS NULL) OR ("status" = 'running' AND "started_at" IS NOT NULL AND "error" IS NULL AND "finished_at" IS NULL) OR ("status" = 'awaiting_review' AND "started_at" IS NOT NULL AND "error" IS NULL AND "finished_at" IS NULL) OR ("status" = 'completed' AND "finished_at" IS NOT NULL AND "error" IS NULL) OR ("status" = 'failed' AND "error" IS NOT NULL AND "finished_at" IS NOT NULL) OR ("status" = 'cancelled' AND "finished_at" IS NOT NULL AND "error" IS NULL) OR ("status" NOT IN ('pending', 'running', 'awaiting_review', 'completed', 'failed', 'cancelled'))) NOT VALID;--> statement-breakpoint

ALTER TABLE "flow_run_steps" ADD CONSTRAINT "flow_run_steps_state_fields_check" CHECK (("status" = 'pending' AND "started_at" IS NULL AND "finished_at" IS NULL AND "error" IS NULL AND "output" IS NULL) OR ("status" = 'running' AND "started_at" IS NOT NULL AND "finished_at" IS NULL AND "error" IS NULL) OR ("status" = 'awaiting_review' AND "started_at" IS NOT NULL AND "finished_at" IS NULL AND "error" IS NULL) OR ("status" = 'completed' AND "finished_at" IS NOT NULL AND "error" IS NULL) OR ("status" = 'failed' AND "error" IS NOT NULL AND "finished_at" IS NOT NULL) OR ("status" = 'skipped' AND "finished_at" IS NOT NULL AND "error" IS NULL) OR ("status" NOT IN ('pending', 'running', 'awaiting_review', 'completed', 'failed', 'skipped'))) NOT VALID;
